llm_sql:
SELECT
    countResample(0, 23, 6)(toHour(timestamp))
FROM events;

SELECT
    countResample(0, 23, 6)(toHour(timestamp)) AS bucket_counts
FROM events;

SELECT
    countResample(0, 23, 6)(toHour(timestamp)) AS bucket_counts
FROM events;

SELECT
    countResample(21600)(
        toUInt8(1),
        toDateTime('1970-01-01 00:00:00', 'UTC') + toIntervalHour(toHour(timestamp))
    ) AS counts
FROM events;

SELECT count(DISTINCT k) FROM (
    SELECT arrayJoin(mapKeys(properties)) AS k
    FROM events
    WHERE event_type = 'purchase'
      AND toDate(timestamp) = '2024-03-01'
);
